  $masojson${"slug": "media-and-society", "title": "Media and Society", "description": "A critical introduction to the relationship between media institutions, journalism, platforms, culture, democracy, identity, power, and social change.", "topics": [{"id": "557e2954-393d-4859-9c16-6143188cd2d3", "type": "topic", "title": "Media, Democracy, and the Public Sphere", "description": "Students examine how media make democratic life possible while also shaping whose voices count in public debate.", "children": [{"id": "f348663c-1db9-4b10-8a92-a73b3e7df3f2", "type": "subtopic", "title": "The public sphere", "children": [{"id": "035e2f07-3e20-4714-a536-20a483abb1c0", "type": "concept", "title": "deliberation"}, {"id": "fa5cf0eb-de09-4732-a717-2d76a02bae8c", "type": "concept", "title": "public forums"}, {"id": "cf341fbd-7957-4e3b-8c36-0d7d30390a46", "type": "concept", "title": "civic information needs"}], "description": "Students learn how media spaces enable citizens to encounter issues, arguments, evidence, and one another."}, {"id": "9b4d26b4-14e6-4161-b180-7136cfc4c94d", "type": "subtopic", "title": "Watchdog and accountability roles", "children": [{"id": "9ff4499f-00e0-41a1-a8fb-116a9d4ccc0d", "type": "concept", "title": "watchdog reporting"}, {"id": "186f79dd-476f-4d4c-866c-0b5ae7b04c12", "type": "concept", "title": "public records"}, {"id": "13ca968c-a412-4078-8172-85b47c1135b5", "type": "concept", "title": "institutional accountability"}], "description": "The course connects journalism to scrutiny of power, public records, investigations, and institutional transparency."}, {"id": "b5900ca0-ad47-4381-be10-970c22386a5b", "type": "subtopic", "title": "Participation and civic voice", "children": [{"id": "500a70e3-e4de-422b-8d61-748162e40592", "type": "concept", "title": "letters and comments"}, {"id": "5d91011c-e1ed-4b84-9cd5-e471d3dee239", "type": "concept", "title": "community media"}, {"id": "11e74f35-2324-4acf-be52-eb4321a940f4", "type": "concept", "title": "participatory journalism"}], "description": "Students consider how audiences, communities, and movements use media to speak back."}, {"id": "b7ad14e2-edd8-433f-9b5c-f028e94ac99e", "type": "subtopic", "title": "Democratic vulnerabilities", "children": [{"id": "9ea5f683-e1e1-4236-921d-812810c94541", "type": "concept", "title": "cynicism"}, {"id": "b9b51b1f-78d0-4741-8fd9-d026f4a17380", "type": "concept", "title": "attention capture"}, {"id": "68083719-3507-425a-8546-4b92ac595832", "type": "concept", "title": "unequal access"}], "description": "The unit names ways media can weaken democracy through exclusion, spectacle, manipulation, or distrust."}]}, {"id": "85f67259-d7ef-4a6a-ad77-20db90c48125", "type": "topic", "title": "Media and Public Opinion", "description": "This section shows how media influence what publics notice, discuss, fear, trust, and demand from institutions.", "children": [{"id": "b8a7e4eb-636b-45f8-97d2-12d23935f01a", "type": "subtopic", "title": "Agenda-setting", "children": [{"id": "7002cb90-fe00-4775-b3b5-ef1b281a9b0a", "type": "concept", "title": "issue salience"}, {"id": "a225bfa9-f23b-466d-9c43-3693c3666474", "type": "concept", "title": "news agendas"}, {"id": "7f1bebb8-25bd-47fd-a381-14a5b8ba7466", "type": "concept", "title": "attention cycles"}], "description": "Students learn how repeated attention to issues can make them feel publicly important."}, {"id": "21d049e8-5b42-4344-bcf6-e4e2266e1038", "type": "subtopic", "title": "Framing", "children": [{"id": "d7a7da30-45b9-4fb4-9d9b-e8c6466aef3a", "type": "concept", "title": "problem definitions"}, {"id": "fdd46940-4fa4-42c1-940b-92207aaadf5a", "type": "concept", "title": "causal stories"}, {"id": "87d1063d-1e8d-49b1-9979-0a6692115117", "type": "concept", "title": "moral evaluations"}], "description": "The class examines how word choice, sources, images, and story structure shape interpretation."}, {"id": "83a4d4f9-4dd5-453c-a753-e0c1b41b8bcc", "type": "subtopic", "title": "Polling and public mood", "children": [{"id": "f3c23dcb-215d-4b4b-8e94-b5bf8d783388", "type": "concept", "title": "sampling"}, {"id": "adf0f346-8317-4583-8b05-bd1a8a874d39", "type": "concept", "title": "margin of error"}, {"id": "6a37a9a5-36cd-4887-a2b1-db7b849b4870", "type": "concept", "title": "opinion trends"}], "description": "Students learn to read polls, trend data, and audience research with care."}, {"id": "bbe272d1-24cd-44e1-a8f8-76c7bb660105", "type": "subtopic", "title": "Trust and credibility", "children": [{"id": "a56ee861-36a0-48db-bd64-9df7bdc4f0cd", "type": "concept", "title": "institutional trust"}, {"id": "94add1aa-d37e-4dd0-95ff-c4dd7d8ebf8b", "type": "concept", "title": "source credibility"}, {"id": "1c46abc7-4a84-45b4-8798-b504525ad00d", "type": "concept", "title": "transparency"}], "description": "Students explore how media trust is built, lost, measured, and affected by identity and politics."}]}, {"id": "c562e0ca-010f-4298-ae1a-7ad98f80079c", "type": "topic", "title": "Media Ownership, Concentration, and Political Economy", "description": "Students learn that media content and access are shaped by who owns outlets, who funds them, and what incentives govern the system.", "children": [{"id": "9d9609f0-edc1-457e-8eb7-f3d5d404a24f", "type": "subtopic", "title": "Ownership structures", "children": [{"id": "10aab7b8-a426-467a-8623-15b9ff73e3d1", "type": "concept", "title": "conglomerates"}, {"id": "26d67301-688b-4230-8414-8e0f55eb3988", "type": "concept", "title": "public media"}, {"id": "b82ee6ed-877d-4b1c-85c6-85ce2d873753", "type": "concept", "title": "nonprofit news"}], "description": "Students compare corporate, family-owned, nonprofit, public, cooperative, and state-backed media models."}, {"id": "a620ed9a-28a9-4bd3-8db0-89439281a8ec", "type": "subtopic", "title": "Concentration and local news", "children": [{"id": "aecb4848-dd68-4f64-85e7-14cfae892806", "type": "concept", "title": "market consolidation"}, {"id": "f6f5ab91-d062-4c2a-9cc4-08447d2859bb", "type": "concept", "title": "local news deserts"}, {"id": "df2642e8-d8e4-498c-927a-e46c3e4a50ef", "type": "concept", "title": "community impact"}], "description": "The class studies consolidation, local news decline, hedge-fund ownership, and news deserts."}, {"id": "12b9e495-8f7e-4e2b-953f-04362b9661cc", "type": "subtopic", "title": "Revenue and incentives", "children": [{"id": "319bf8ea-4792-4ff7-9e0b-c952917e2519", "type": "concept", "title": "advertising"}, {"id": "32a5afa0-1ad0-4494-ba49-ace5e5c133da", "type": "concept", "title": "subscriptions"}, {"id": "12a7b0ab-3e28-41d5-be93-79732ae3d2fc", "type": "concept", "title": "audience revenue"}], "description": "Students analyze how ads, subscriptions, philanthropy, sponsorships, and platform traffic influence priorities."}, {"id": "b51d5a49-782b-40c4-b824-cde0a0d300e7", "type": "subtopic", "title": "Labor and inequality", "children": [{"id": "fffd9395-f60a-4db0-a8b4-78a3ca7dce7c", "type": "concept", "title": "freelance labor"}, {"id": "3cfebeb1-adb9-4d5f-a32c-278928361df2", "type": "concept", "title": "unions"}, {"id": "2d14ef4a-975b-42d5-b373-07f1bbd0e693", "type": "concept", "title": "access to careers"}], "description": "The unit considers newsroom jobs, freelancing, unions, precarity, and who can afford media work."}]}, {"id": "1b9af14d-244b-41f5-8ea7-383fd4b10a11", "type": "topic", "title": "Representation, Diversity, and Social Identity", "description": "This unit asks students to study media as a site where identity, belonging, stereotypes, and social power are produced and contested.", "children": [{"id": "77258cc6-a7f8-467d-9d82-3d4293e047e6", "type": "subtopic", "title": "Representation and stereotypes", "children": [{"id": "fe65df40-b575-4cbf-bbd8-62c3fc4bb6c6", "type": "concept", "title": "symbolic annihilation"}, {"id": "59c3be54-807c-46c7-9b72-0e72d6da4dbe", "type": "concept", "title": "stereotype formation"}, {"id": "4288c22b-b9b3-451f-bcdd-9ac04c4cbc3b", "type": "concept", "title": "counter-stereotypes"}], "description": "Students examine recurring patterns in portrayals of race, gender, class, sexuality, religion, disability, and nationality."}, {"id": "5b8d6955-3d49-4407-ab53-3a6ba487ad7a", "type": "subtopic", "title": "Source diversity", "children": [{"id": "6a527f16-a1d9-4d6f-92b4-3d5a989e4df9", "type": "concept", "title": "source audits"}, {"id": "6a4f95c7-b3c1-4399-8e48-cfa8dfba19e3", "type": "concept", "title": "expertise and authority"}, {"id": "3ae356ae-5492-4283-9b76-b3064825b04b", "type": "concept", "title": "community knowledge"}], "description": "The course connects representation to who gets quoted, centered, trusted, and treated as expert."}, {"id": "7e764e70-4c0e-413e-b0ff-9c681666079a", "type": "subtopic", "title": "Audience interpretation", "children": [{"id": "d67da329-094c-45e4-bcd9-ff260c18f794", "type": "concept", "title": "encoding/decoding"}, {"id": "ab8e8190-0c29-4592-a092-bee665bec753", "type": "concept", "title": "interpretive communities"}, {"id": "01da9c25-0c55-44db-a640-478d22a59b1e", "type": "concept", "title": "oppositional readings"}], "description": "Students learn that audiences read media through lived experience, identity, culture, and context."}, {"id": "afee91aa-f3c6-40f9-a180-51ffbc40665f", "type": "subtopic", "title": "Inclusive media practice", "children": [{"id": "3fd14130-f99b-4464-b31c-a2687b52d995", "type": "concept", "title": "style choices"}, {"id": "1344d538-00e6-4a5c-a4c5-9fe523a436a7", "type": "concept", "title": "community listening"}, {"id": "deb9c75a-1fe9-4c76-8b1d-5ee8059859cb", "type": "concept", "title": "contextual reporting"}], "description": "Students identify practices that improve accuracy and reduce harm."}]}, {"id": "f928f7c1-158c-43d2-bfdf-11458ea925a8", "type": "topic", "title": "Media Literacy and Critical Consumption", "description": "Students build durable habits for evaluating media claims, recognizing persuasion, and understanding how messages are constructed.", "children": [{"id": "583640d6-6af3-480a-9e82-1f7604bd528e", "type": "subtopic", "title": "Lateral reading", "children": [{"id": "8c32ce4b-6766-48ed-b56c-c7c63c712d56", "type": "concept", "title": "source tracing"}, {"id": "4b249ddf-d60f-47dc-a43f-9acf7b5f2168", "type": "concept", "title": "about pages"}, {"id": "56d008df-b9bb-48d8-9d09-d8a8a689ce5f", "type": "concept", "title": "independent confirmation"}], "description": "Students learn to leave a source, check context, and compare claims across credible evidence."}, {"id": "13b74beb-b537-4b19-9df4-f94c2445e0cd", "type": "subtopic", "title": "Message construction", "children": [{"id": "07eed1a9-43ca-469a-b272-ef7f403db240", "type": "concept", "title": "visual rhetoric"}, {"id": "e63e3796-58e4-4c06-a412-3873966f182d", "type": "concept", "title": "headline framing"}, {"id": "3e086ef7-235f-469a-9edd-774d0971daba", "type": "concept", "title": "selective evidence"}], "description": "The class analyzes how headlines, images, editing, sound, statistics, and design guide interpretation."}, {"id": "2ec7c1cf-9bef-4fcb-84cd-435b39f23dfb", "type": "subtopic", "title": "Attention and emotion", "children": [{"id": "ccddbac7-d1ec-4f28-9fe6-421273ea2284", "type": "concept", "title": "emotional triggers"}, {"id": "9cd707da-c81a-4fd8-b12f-b280d661fc62", "type": "concept", "title": "virality"}, {"id": "f6d6d73d-528a-462a-bf6c-ee97e3ffb2ba", "type": "concept", "title": "confirmation bias"}], "description": "Students study how outrage, fear, humor, novelty, and identity drive sharing and memory."}, {"id": "d4412ba6-88c3-4379-88d1-7f49541f3c33", "type": "subtopic", "title": "Everyday media habits", "children": [{"id": "9af27e27-b80a-4cf1-8d08-0c3b4e078b9a", "type": "concept", "title": "news diets"}, {"id": "5f081a66-a1ac-44b6-97ed-8449ed062219", "type": "concept", "title": "platform habits"}, {"id": "60f2c3e1-1c5a-4c9a-be70-bb1da6b2cf1f", "type": "concept", "title": "information hygiene"}], "description": "Students reflect on their own feeds, subscriptions, notifications, and routines."}]}, {"id": "27f2bb20-041a-48db-9f0a-38538ed7b4f4", "type": "topic", "title": "Propaganda, Persuasion, and Strategic Influence", "description": "This section helps students distinguish legitimate persuasion from manipulative influence and organized information campaigns.", "children": [{"id": "13ce6bd4-133b-44e6-8b83-be6de4d23216", "type": "subtopic", "title": "Persuasion principles", "children": [{"id": "e3336a22-6546-41e9-a2a0-a76255c22422", "type": "concept", "title": "ethos/pathos/logos"}, {"id": "99c8875f-b9bb-4033-ab74-0ec6c5fb7052", "type": "concept", "title": "social proof"}, {"id": "e027d823-847e-46ff-84b1-8611a948d9ad", "type": "concept", "title": "narrative persuasion"}], "description": "Students study emotional appeals, credibility, repetition, social proof, and narrative identification."}, {"id": "b592ebb6-3ae6-44f7-9213-b0b44e5251d2", "type": "subtopic", "title": "Propaganda techniques", "children": [{"id": "b08f3b45-5a05-4295-92fe-8a17eb2ace41", "type": "concept", "title": "name-calling"}, {"id": "4e39bee7-693c-4db7-a166-4043ca0b3ea9", "type": "concept", "title": "glittering generalities"}, {"id": "a36d9ab3-d364-4e0c-a80d-6af4ce11d7f2", "type": "concept", "title": "fear appeals"}], "description": "The class identifies simplification, scapegoating, bandwagon appeals, fear appeals, and false dilemmas."}, {"id": "c175bba1-c8d0-4c2e-b87b-f7586fc8a892", "type": "subtopic", "title": "Institutional messaging", "children": [{"id": "792b6637-63f5-469c-ad07-f326249de11e", "type": "concept", "title": "press offices"}, {"id": "5e448595-3873-4359-8da6-1f19bdf13491", "type": "concept", "title": "crisis messaging"}, {"id": "77e5f9bc-117f-406d-9150-2455174dcf65", "type": "concept", "title": "advocacy campaigns"}], "description": "Students analyze government, corporate, nonprofit, and political communication strategies."}, {"id": "d32e2dff-e0ce-460a-a916-3835c8a11d15", "type": "subtopic", "title": "Influence operations", "children": [{"id": "ce3e834c-bb10-4ec1-93c8-965addf716d1", "type": "concept", "title": "bots and trolls"}, {"id": "e267e1e7-3991-475e-a2f2-44cd15fb853d", "type": "concept", "title": "astroturfing"}, {"id": "8db033e1-279a-4726-b22b-9ad026d827da", "type": "concept", "title": "coordinated inauthentic behavior"}], "description": "Students learn how coordinated campaigns manipulate visibility, authenticity, and trust."}]}, {"id": "6ac8cb3c-f578-48e9-87d9-9ba611057488", "type": "topic", "title": "Media and Politics", "description": "Students examine how political communication, journalism, campaigns, and platforms shape democratic competition and governance.", "children": [{"id": "639c45d3-8918-4813-a87c-ad379722b22b", "type": "subtopic", "title": "Campaign communication", "children": [{"id": "d371b655-357b-4c1a-bf8e-8552cca2e8bd", "type": "concept", "title": "political ads"}, {"id": "e9c7fe0e-f635-492a-a7ad-d51361cfa2e1", "type": "concept", "title": "debates"}, {"id": "62f36275-2851-4139-9dc5-6058b46ab574", "type": "concept", "title": "microtargeting"}], "description": "The course covers ads, debates, rallies, social media strategy, opposition research, and voter targeting."}, {"id": "26336c5d-0b0d-45a6-a552-fa9f7e653e87", "type": "subtopic", "title": "Government and press relations", "children": [{"id": "5934bdae-a1bf-46b6-9a04-3cc8407b8e91", "type": "concept", "title": "press briefings"}, {"id": "9381e113-34a7-42ac-b3f9-524a79190191", "type": "concept", "title": "leaks"}, {"id": "0b9db544-c0ba-4047-9e0e-6ceabc699b35", "type": "concept", "title": "spin"}], "description": "Students learn how officials manage access, leaks, briefings, and narratives."}, {"id": "da16dc98-4e00-4757-80ae-beec34d4b3a3", "type": "subtopic", "title": "Polarization and partisan media", "children": [{"id": "b922837a-b1ae-4903-9e19-6691f079ae68", "type": "concept", "title": "echo chambers"}, {"id": "0e9e8566-743e-44ad-a5b3-23fe66e5bba9", "type": "concept", "title": "partisan outlets"}, {"id": "721aa382-6c8e-4ea1-9724-63b551b61d0d", "type": "concept", "title": "affective polarization"}], "description": "The class analyzes fragmented information environments and identity-driven media use."}, {"id": "c0eb17d3-f496-4f3d-a7eb-8bb3dbe4de6e", "type": "subtopic", "title": "Election information integrity", "children": [{"id": "5f57df74-42f7-4e8b-96e4-086eb127c66f", "type": "concept", "title": "election misinformation"}, {"id": "2279e1f6-b829-4d2b-9da7-39ebd72cc801", "type": "concept", "title": "results reporting"}, {"id": "f0bf8ebb-72c5-422d-bd24-f9b23df2ca15", "type": "concept", "title": "democratic legitimacy"}], "description": "Students study how media affect voting information, legitimacy, and public confidence."}]}, {"id": "a8039467-7588-4e58-b967-54a7556f6cf2", "type": "topic", "title": "Social Media, Platforms, and Networked Publics", "description": "Students learn how social platforms reorganize public conversation, visibility, status, activism, harassment, and news distribution.", "children": [{"id": "538dd42e-0960-42af-b4de-23652ba501b8", "type": "subtopic", "title": "Platform affordances", "children": [{"id": "8711a5f6-af5b-44fe-bbfc-8fdf082fd795", "type": "concept", "title": "feeds"}, {"id": "b4d66b49-0a67-4836-96cb-ab913dec33a8", "type": "concept", "title": "hashtags"}, {"id": "f613a861-47f1-49d1-9bb8-242945685341", "type": "concept", "title": "engagement signals"}], "description": "Students analyze how likes, shares, hashtags, feeds, comments, and short video shape behavior."}, {"id": "d4458723-3a48-452e-9d19-403e5cc0881e", "type": "subtopic", "title": "Networked publics", "children": [{"id": "c5a49b0b-9c4b-4ec0-9163-48e616d3f04d", "type": "concept", "title": "networked identity"}, {"id": "3c56d580-3e08-417d-8c85-2e1e492376a5", "type": "concept", "title": "context collapse"}, {"id": "4463f21c-7d24-4acc-a9fb-a1d25c7d6c43", "type": "concept", "title": "online communities"}], "description": "The course explains how communities form, mobilize, fragment, and clash online."}, {"id": "f10aacbc-164f-4bf6-9cf5-ae951bfd5bd2", "type": "subtopic", "title": "Content moderation", "children": [{"id": "51e06dd2-0dd1-4dad-b6e0-2f6de5239c33", "type": "concept", "title": "community standards"}, {"id": "6ef5d265-a03e-4acb-8461-75c6be29e1a6", "type": "concept", "title": "deplatforming"}, {"id": "1fc36fe6-5bc7-4045-abe3-bc6a8ea121a9", "type": "concept", "title": "moderation labor"}], "description": "Students learn the social stakes of platform rules, enforcement, appeals, and speech governance."}, {"id": "c02eeaa6-402b-4aec-a113-c0dc742f3d84", "type": "subtopic", "title": "Harassment and safety", "children": [{"id": "ae70cdc1-26eb-4a24-9e4e-a5ac82f6bd74", "type": "concept", "title": "online harassment"}, {"id": "5852e5ce-4a6a-49a6-b77a-fb209df4887c", "type": "concept", "title": "doxxing"}, {"id": "d51389a7-f1eb-4993-a8a0-790e515ba47a", "type": "concept", "title": "journalist safety"}], "description": "The unit covers abuse, doxxing, threats, and unequal burdens of participation."}]}, {"id": "af27b952-4e01-4145-9555-9b608b17dc41", "type": "topic", "title": "Global Media Systems and Comparative Perspectives", "description": "This unit moves beyond a U.S.-only frame so students can compare media systems, press freedom, regulation, and cultural flows worldwide.", "children": [{"id": "7baebdb7-33a9-43bc-bc7f-4414c75c4603", "type": "subtopic", "title": "Comparative media systems", "children": [{"id": "d658f812-47ea-492f-a166-93d75c676036", "type": "concept", "title": "public broadcasting"}, {"id": "15b047a9-3b6f-4743-820b-fe2b6006729e", "type": "concept", "title": "state media"}, {"id": "75a5a28a-ad92-482d-a325-46f504ea5309", "type": "concept", "title": "commercial systems"}], "description": "Students compare liberal, democratic-corporatist, polarized-pluralist, public-service, state-controlled, and hybrid systems."}, {"id": "50fb8e2d-9482-4104-ab03-0e668fac13a0", "type": "subtopic", "title": "Global news flows", "children": [{"id": "bd499db0-1603-4faf-b6d7-c0ddbd17977d", "type"