visibility"}], "description": "Students connect protest, organizing, hashtags, live video, and movement storytelling."}, {"id": "6e8fb768-9aa6-4098-9310-d00a152acf2b", "type": "subtopic", "title": "Advocacy journalism and solutions journalism", "children": [{"id": "5f615e75-2a18-4ad7-9391-8d9e93814715", "type": "concept", "title": "solutions journalism"}, {"id": "b6ad9d66-78b1-4592-93a8-44101183de67", "type": "concept", "title": "advocacy boundaries"}, {"id": "388b9072-d603-469b-8aed-3f952e412280", "type": "concept", "title": "public service"}], "description": "The class compares watchdog, explanatory, advocacy, and solutions-oriented approaches."}, {"id": "aee78571-8206-4642-8cca-e0a07038b4de", "type": "subtopic", "title": "Media events and moral shocks", "children": [{"id": "9821b612-7963-4652-aaba-ab0de880703c", "type": "concept", "title": "viral images"}, {"id": "5c3fb823-19a7-4f3f-a7f9-ab3652f23621", "type": "concept", "title": "focusing events"}, {"id": "ef8ac5cf-1071-4ad5-885f-808017ab57c1", "type": "concept", "title": "moral shock"}], "description": "Students learn how images, stories, and events can suddenly shift public attention."}, {"id": "aa7d309b-7044-45af-9137-2aee95e91aca", "type": "subtopic", "title": "Backlash and co-optation", "children": [{"id": "c30ef402-2650-4a2a-8c9d-aeac23bebd86", "type": "concept", "title": "counter-mobilization"}, {"id": "6de04c2c-432d-4716-b0ee-a0a8250d96bd", "type": "concept", "title": "brand activism"}, {"id": "5db82cf8-8f0d-454f-9c25-4ea4c9cf4f51", "type": "concept", "title": "surveillance of movements"}], "description": "The unit examines how movements can be distorted, commercialized, surveilled, or opposed."}]}, {"id": "9792829c-3579-4d5f-af20-59e2e68db3c5", "type": "topic", "title": "Misinformation, Trust, and Information Disorder", "description": "This added unit gives students a rigorous framework for polluted information environments without flattening all error into the same category.", "children": [{"id": "b283